import{_ as a,o,c as n,a2 as i}from"./chunks/framework.A5mep7Fe.js";const d=JSON.parse('{"title":"🐍 01 · Python（AI 开发第一语言）","description":"","frontmatter":{},"headers":[],"relativePath":"06-开发岗-编程语言与工程/01-Python.md","filePath":"06-开发岗-编程语言与工程/01-Python.md","lastUpdated":1786806808000}'),e={name:"06-开发岗-编程语言与工程/01-Python.md"};function l(r,t,s,c,h,p){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="🐍-01-·-python-ai-开发第一语言" tabindex="-1">🐍 01 · Python（AI 开发第一语言） <a class="header-anchor" href="#🐍-01-·-python-ai-开发第一语言" aria-label="Permalink to &quot;🐍 01 · Python（AI 开发第一语言）&quot;">​</a></h1><blockquote><p>AI 算法/应用开发几乎默认 Python。面试考「底层理解 + 工程能力」，不只调包。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>GIL（全局解释器锁）</strong>：同一进程内同刻仅一个线程执行字节码 → CPU 密集任务多线程无效，用多进程/异步/C 扩展。</li><li><strong>可变对象陷阱</strong>：默认参数用可变对象（list/dict）导致的共享状态 bug。</li><li><strong>深拷贝/浅拷贝</strong>：引用语义易被忽视。</li><li><strong>装饰器</strong>：函数包装，用于日志/缓存/鉴权。</li><li><strong>生成器/yield</strong>：惰性计算，省内存（处理大模型流式输出常用）。</li><li><strong>类型标注（Type Hint）</strong>：大型项目必备（mypy/pydantic）。</li><li><strong>异步 asyncio</strong>：高并发 IO（LLM 流式调用、批量请求）。</li></ul><h2 id="二、性能与工程" tabindex="-1">二、性能与工程 <a class="header-anchor" href="#二、性能与工程" aria-label="Permalink to &quot;二、性能与工程&quot;">​</a></h2><ul><li>性能瓶颈用 Cython / Numba / 调 C++ 扩展</li><li>并发：IO 密集用 asyncio；CPU 密集用 multiprocessing</li><li>虚拟环境（venv/conda）、依赖管理（poetry/uv）</li><li>代码质量：lint（ruff/flake8）、format（black）、测试（pytest）</li></ul><h2 id="三、ai-生态结合" tabindex="-1">三、AI 生态结合 <a class="header-anchor" href="#三、ai-生态结合" aria-label="Permalink to &quot;三、AI 生态结合&quot;">​</a></h2><ul><li>推理：OpenAI/Anthropic SDK、LangChain/LlamaIndex（谨慎用重框架）</li><li>模型：transformers、vLLM（推理服务）、torch</li><li>数据：numpy/pandas、向量库 client</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：Python 怎么真正并行？</strong></p><blockquote><p>用 multiprocessing（绕过 GIL，多进程各一解释器）或把热点用 C/C++/Rust 扩展；IO 并发用 asyncio。</p></blockquote><p><strong>Q2：asyncio 适合什么场景？</strong></p><blockquote><p>高并发 IO（如同时向 LLM 发几百个请求、流式输出），但 CPU 密集任务仍被 GIL 限制。</p></blockquote><p><strong>Q3：大项目怎么保证质量？</strong></p><blockquote><p>类型标注 + 严格 lint/format + 单测/集成测试 + CI + code review + pydantic 做数据校验。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-Java">02-Java</a></p>',18)])])}const g=a(e,[["render",l]]);export{d as __pageData,g as default};
